    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==col and not seen[r][c]:
                st=[(r,c)]; cells=[]
                while st:
                    rr,cc=st.pop()
                    if seen[rr][cc]: continue
                    seen[rr][cc]=True; cells.append((rr,cc))
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            x,y=rr+dr,cc+dc
                            if 0<=x<H and 0<=y<W and g[x][y]==col: st.append((x,y))
                out.append(cells)
    return out
def solve(g):
    Hh,Ww=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    allc=[]
    for col_ in set(x for r in g for x in r)-{bg}:
        for comp in comps(g,col_): allc.append((col_,comp))
    _,fr=max(allc,key=lambda t:len(t[1]))
    fcol=g[fr[0][0]][fr[0][1]]
    c0=min(c for _,c in fr); c1=max(c for _,c in fr)
    solids={r for r in range(Hh) if all(g[r][c]==fcol for c in range(c0,c1+1))}
    bands=[]; cur=None
    for r in range(Hh):
        if r in solids:
            if cur is not None: bands.append(cur)
            cur=None
        else:
            if cur is None: cur=[r]
            else: cur.append(r)
    if cur is not None: bands.append(cur)
    objs=[]
    for col_ in set(x for r in g for x in r)-{bg,fcol}:
        for comp in comps(g,col_):
            rs=[r for r,_ in comp]; cs=[c for _,c in comp]
            objs.append({'top':min(rs),'left':min(cs),'area':len(comp),'cells':sorted(comp),'col':col_})
    objs.sort(key=lambda o:(-(o['top']+o['left']),-o['area']))
    canvas=[[g[r][c] for c in range(c1+1)] for r in range(Hh)]
    for i,b in enumerate(reversed(bands)):
        topb=b[0]
        if i>=len(objs): break
        o=objs[i]
        for rr,cc in o['cells']:
            nr=topb+(rr-min(r for r,_ in o['cells']))
            nc=(cc-min(c for _,c in o['cells']))
            if 0<=nr<Hh and 0<=nc<c1+1 and canvas[nr][nc]!=fcol: canvas[nr][nc]=o['col']
    return canvas
