            if cur is not None: bands.append(cur[:])
            cur=None
        else:
            if cur is None: cur=[r]
            else: cur.append(r)
    if cur is not None: bands.append(cur)
    objs=[]
    for col_ in set(x for r in g for x in r)-{bg,fcol}:
        for comp in comps(g,col_):
            rs=[r for r,_ in comp]; cs=[c for _,c in comp]
            objs.append({'top':min(rs),'left':min(cs),'h':max(rs)-min(rs)+1,'w':max(cs)-min(cs)+1,
                         'cells':[(rr-min(rs),cc-min(cs)) for rr,cc in comp],'col':col_})
    # slide each object left until next step would collide with frame (in its own rows)
    def frame_collides(obj, left):
        for dr,dc in obj['cells']:
            rr=obj['top']+dr; cc=left+dc
            if not(0<=cc<=c1): return True
            if g[rr][cc]==fcol: return True
        return False
    for o in objs:
        left=o['left']
        while left>o['left'] and not frame_collides(o,left-1):
            left-=1
        o['slid_left']=left
    # swap top and bottom band contents, keep middle
    n=len(bands)
    mid=n//2
    if n>1:
        top_band,bottom_band=bands[0],bands[-1]
        objs_by_band={}
        for i,b in enumerate(bands):
            for o in objs:
