        # rebuild: bottom band gets objects originally in top band (same count/order), etc.
        new_objs=[list(objs_by_band.get(i,[])) for i in range(n)]
        new_objs[0]=new_objs[-1][:]
        new_objs[-1]=new_objs[0][:-1] if False else []
        # careful: take copies of the object list references
        new_objs[0]=list(objs_by_band[-1]) if n>1 else objs_by_band.get(0,[])
        new_objs[-1]=list(objs_by_band[0]) if n>1 else objs_by_band.get(-1,[])
        objs=new_objs
    canvas=[[g[r][c] for c in range(c1+1)] for r in range(H)]
    for i,o in enumerate(objs):
        b=bands[i]
        topb=b[0]
        for dr,dc in o['cells']:
            nr=topb+dr; nc=o['slid_left']+dc
            if 0<=nr<H and 0<=nc<=c1: canvas[nr][nc]=o['col']
    return canvas
