def solve(g):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r); bg=cnt.most_common(1)[0][0]
    allc=[]
    for col_ in set(x for r in g for x in r)-{bg}:
        for comp in comps(g,col_): allc.append((col_,comp))
    _,fr=max(allc,key=lambda t:len(t[1]))
    fcol=g[fr[0][0]][fr[0][1]]
    c0=min(c for _,c in fr); c1=max(c for _,c in fr)
    solids={r for r in range(H) if all(g[r][c]==fcol for c in range(c0,c1+1))}
    bands=[]; cur=None
    for r in range(H):
        if r in solids:
            if cur is not None: bands.append(cur[:])
            cur=None
        else:
            if cur is None: cur=[r]
            else: cur.append(r)
    if cur is not None: bands.append(cur)
    objs=[]
    for col_ in set(x for r in g for x in r)-{bg,fcol}:
        for comp in comps(g,col_):
            rs=[r for r,_ in comp]; cs=[c for _,c in comp]
            objs.append({'top':min(rs),'left':min(cs),'cells':[(rr-min(rs),cc-min(cs)) for rr,cc in comp],'col':col_})
    def frame_collides(o,left):
        for dr,dc in o['cells']:
            rr=o['top']+dr; cc=left+dc
            if 0<=cc<=c1 and g[rr][cc]==fcol: return True
        return False
    for o in objs:
        left=o['left']
        while not frame_collides(o,left-1):
            left-=1
        o['slid_left']=left
    n=len(bands)
    by_band={}
    for i,b in enumerate(bands):
        by_band[i]=[o for o in objs if min(b)<=o['top']<=max(b)]
    out_objs=[list(by_band[i]) for i in range(n)]
    if n>1:
        out_objs[0]=list(by_band[-1]); out_objs[-1]=list(by_band[0])
    canvas=[[g[r][c] for c in range(c1+1)] for r in range(H)]
    for i,o in enumerate(out_objs):
        b=bands[i]; topb=b[0]
        for dr,dc in o[0]['cells']:
            nr=topb+dr; nc=o[0]['slid_left']+dc
            if 0<=nr<H and 0<=nc<=c1: canvas[nr][nc]=o[0]['col']
    return canvas

