def load():
    import os,re,collections
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,col):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==col and not seen[r][c]:
                st=[(r,c)]; cells=[]
                while st:
                    rr,cc=st.pop()
                    if seen[rr][cc]: continue
                    seen[rr][cc]=True; cells.append((rr,cc))
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            x,y=rr+dr,cc+dc
                            if 0<=x<H and 0<=y<W and g[x][y]==col: st.append((x,y))
                out.append(cells)
    return out
for k in ['Demo pair 1','Demo pair 2']:
    inp=G[k+' input']; out=G[k+' output']
    H,W=len(inp),len(inp[0])
    cnt=collections.Counter(x for r in inp for x in r); bg=cnt.most_common(1)[0][0]
    al=[(col_,comp) for col_ in set(x for r in inp for x in r)-{bg} for comp in comps(inp,col_)]
    big=max(al,key=lambda t:len(t[1])); fcol=big[0]; fr=big[1]
    c0=min(c for _,c in fr); c1=max(c for _,c in fr)
    print('===',k,'fcol',fcol,'c0',c0,'c1',c1,'W_out',len(out[0]))
    # object cells in input
    objs=[]
    for col_ in set(x for r in inp for x in r)-{bg,fcol}:
        for comp in comps(inp,col_):
            rs=[r for r,_ in comp]; cs=[c for _,c in comp]
            if min(cs)>c1: continue
            objs.append({'col':col_,'cells':sorted(comp),'h':max(rs)-min(rs)+1,'w':max(cs)-min(cs)+1})
    print('objs:',[(o['col'],o['h'],o['w'],o['cells'][0]) for o in objs])
    # output objects per band
    solids={r for r in range(H) if all(inp[r][c]==fcol for c in range(c0,c1+1))}
    bands=[list(range(b[0],b[-1]+1)) for b in []]
    bands=[];cur=None
